// One ownership/control model; legal form changes the guidance, not the identity records.
(()=>{const q=s=>document.querySelector(s),screen=q('[data-screen="4"]');labels[4]='Ownership & control';screen.querySelector('h1').textContent='Ownership & control';screen.querySelector('.lead').textContent='Identify the people who own or control this entity. Enter each person once, with their relevant roles.';
const obsolete=q('#nonshare-structure')?.closest('section');if(obsolete){obsolete.hidden=true;obsolete.querySelectorAll('input,textarea').forEach(e=>e.required=false);}
const section=q('#ubos').closest('section');section.querySelector('h2').textContent='Owners, controllers & governing persons';section.querySelector('.hint').textContent='Include relevant beneficial owners and people exercising control. A controlling or governing person may have no ownership percentage. The applicable test depends on the entity and jurisdiction.';
const clarification=document.createElement('label');clarification.className='field';clarification.innerHTML='<span>Ownership or control clarification (optional)</span><textarea id="ownership-clarification" placeholder="For example, dispersed shareholding, indirect control, or information that still needs verification."></textarea>';section.append(clarification);
function sync(){const type=q('#entity-type').value,nonshare=['Foundation','Association','Partnership','Limited liability partnership (LLP)','Other legal entity'].includes(type);section.hidden=false;obsolete.hidden=true;section.querySelector('h2').textContent=nonshare?'Relevant owners, controllers & governing persons':'Owners & controlling persons';section.querySelectorAll('.pct').forEach(e=>e.closest('label').querySelector('span').textContent='Ownership % (if applicable)');const actions=screen.querySelector('.actions');if(actions)screen.append(actions);}
q('#entity-type').addEventListener('change',sync);const refresh=refreshFlow;refreshFlow=function(){refresh();sync();};
document.addEventListener('change',()=>queueMicrotask(()=>document.querySelectorAll('.country-picker').forEach(h=>{if(h.__values)h.querySelector('summary').textContent=h.__values().join(', ')||'Select countries';})));
const evidence=q('#pb-evidence');[...evidence.options].filter(o=>o.textContent==='I would like guidance on what is needed').forEach(o=>o.remove());if(![...evidence.options].some(o=>o.value==='Not currently available'))evidence.add(new Option('Not currently available'));
sync();})();
